begin read only;set local search_path=pg_catalog;with w as(select id,status,business_support_version from public.budget_workspaces where name='audit-batch-x-receipt-d7be160c2026') select jsonb_build_object('matched_fixture',(select count(*) from w),'fixture_suspended',(select status='suspended' from w),'support_version',(select business_support_version from w),'subscription',(select jsonb_build_object('member_limit',member_limit,'version',version,'status',status) from public.workspace_subscriptions where workspace_id in(select id from w)),'active_members',(select count(*) from public.workspace_members where workspace_id in(select id from w) and status='active'),'pending_invites',(select count(*) from public.workspace_invitations where workspace_id in(select id from w) and status='pending'),'new_request_rows',(select count(*) from public.business_spending_requests where workspace_id in(select id from w) and title='Synthetic request bill lifecycle 20261107' and status='fulfilled'),'new_bill_rows',(select count(*) from public.business_bills where workspace_id in(select id from w) and reference='AUDIT-X-FINANCE-20261107' and status='paid' and amount=1 and paid_amount=1),'new_payment_rows',(select count(*) from public.business_bill_payments p join public.business_bills b on b.id=p.bill_id where b.workspace_id in(select id from w) and b.reference='AUDIT-X-FINANCE-20261107'),'new_payment_total',(select sum(p.amount) from public.business_bill_payments p join public.business_bills b on b.id=p.bill_id where b.workspace_id in(select id from w) and b.reference='AUDIT-X-FINANCE-20261107'),'new_supplier_rows',(select count(*) from public.business_suppliers where workspace_id in(select id from w) and name='Synthetic finance audit supplier 20261107'),'physical_objects',(select count(*) from storage.objects where bucket_id='business-documents' and split_part(name,'/',2) in(select id::text from w)),'remaining_CI_sessions',(select count(*) from auth.sessions where user_agent in('Mushavo-Staging-Runner/42355118392/1','Mushavo-Staging-Runner/42355292667/1','Mushavo-Staging-Runner/42356288736/1')),'remaining_compensation_sessions',(select count(*) from auth.sessions where user_agent='Mushavo-Finance-Isolation-Compensation/20261107'),'normal_queue_rows',(select count(*) from public.notification_outbox),'admin_queue_rows',(select count(*) from public.admin_notification_outbox),'catalog_matches',(select catalog_sha256=mushavo_email_install.catalog_identity() and mode='ACTIVE' and target_project='dczlddwbtgvfdujgcitb' from mushavo_email_install.rollout_control where singleton)) readback;rollback;
